
<template>

<div class="container" style="max-width: 400px; margin-top: 40px;"> <div class="card"> <h3 class="form-title">注册</h3> <p v-if="error" class="error">{{ error }}</p> <input v-model="form.username" placeholder="用户名（至少3位）" /> <input v-model="form.nickname" placeholder="昵称（可选）" /> <input v-model="form.password" type="password" placeholder="密码（至少6位）" /> <button :disabled="loading" @click="submit"> {{ loading ? '注册中...' : '注册' }} </button> <p class="tip" style="margin-top: 12px;"> 已有账号？<router-link to="/login">去登录</router-link> </p> </div> </div> </template><script setup> import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useUserStore } from '../stores/user'; const form = reactive({ username: '', nickname: '', password: '' }); const error = ref(''); const loading = ref(false); const store = useUserStore(); const router = useRouter(); async function submit() { error.value = ''; if (!form.username || !form.password) { error.value = '请输入用户名和密码'; return; } loading.value = true; try { await store.register({ ...form }); router.push('/home'); } catch (e) { error.value = e.message || '注册失败'; } finally { loading.value = false; } } </script>
